<template>
  
    <div class="rowSpaceBetween fullWidth">
      <TopDeck firstElement="Santé" />
    </div>

    <div class="healthContainer">
      <!-- Bloc IMC -->
      <div class="healthBloc">
        <h3>Indice de Masse Corporelle (IMC)</h3>

        <!-- Barre horizontale avec zones -->
        <div class="imcBar">
          <div class="zone under"></div>
          <div class="zone normal"></div>
          <div class="zone overweight"></div>
          <div class="zone obese"></div>
          <!-- Indicateur utilisateur -->
          <div
            class="indicator"
            :style="{ left: bmiPercent + '%' }"
          ></div>
        </div>

        <p class="mt-3">
          <strong>Votre IMC :</strong> {{ bmi.toFixed(1) }} – {{ bmiStatus }}
        </p>
      </div>

      <!-- Bloc dépense énergétique -->
      <div class="healthBloc">
        <h3>Dépenses énergétiques</h3>
        <p><strong>Taux métabolique de base :</strong> {{ tmb.toFixed(0) }} kcal / jour</p>
        <p><strong>Niveau d’activité :</strong> {{ $t(activityLevel) }}</p>
        <p><strong>Besoins énergétiques journaliers :</strong> {{ dailyNeeds.toFixed(0) }} kcal / jour</p>
        <p><strong>Objectif :</strong> {{ $t(weightObjective) }}</p>
        <p><strong>Objectif :</strong> {{ authStore.userInfos?.actualWeight }} Kg</p>

        <!-- Cases résultat -->
        <div class="resultCards">
          <div class="card neutral">
            <p>Taux métabolique de base</p>
            <strong>{{ tmb.toFixed(0) }} kcal</strong>
          </div>
          <div class="card target">
            <p>Calories visées</p>
            <strong>{{ targetCalories.toFixed(0) }} kcal</strong>
          </div>
        </div>
      </div>

      <!-- Bloc répartition macros -->
      <div class="healthBloc">
        <h3>Répartition des macronutriments</h3>
        <div class="macros">
          <div class="macro protein">
            <p>Protéines</p>
            <strong>{{ proteinNeeds.toFixed(0) }} g</strong>
          </div>
          <div class="macro fat">
            <p>Lipides</p>
            <strong>{{ fatNeeds.toFixed(0) }} g</strong>
          </div>
          <div class="macro carb">
            <p>Glucides</p>
            <strong>{{ carbNeeds.toFixed(0) }} g</strong>
          </div>
        </div>
      </div>
    </div>
</template>

<script>
import { computed } from "vue";
import TopDeck from "../Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";

export default {
  name: "HealthPage",
  components: { TopDeck },
  setup() {
    const authStore = useAuthStore();

    // Données issues du profil
    const weight = authStore.userInfos?.actualWeight || 70;
    const height = authStore.userInfos?.actualSize || 175;
    const age = authStore.userInfos?.age || 30;
    const sex = authStore.userInfos?.sex || "male";
    const activityLevel = authStore.userInfos?.activityLevel || "sedentary";
    const weightObjective = authStore.userInfos?.weightObjective || "maintainWeight";

    // IMC calcul
    const bmi = computed(() => {
      const h = height / 100;
      return weight / (h * h);
    });

    const bmiStatus = computed(() => {
      if (bmi.value < 18.5) return "Insuffisance pondérale";
      if (bmi.value < 25) return "Poids normal";
      if (bmi.value < 30) return "Surpoids";
      return "Obésité";
    });

    // Position indicateur IMC (barre de 0 à 40)
    const bmiPercent = computed(() => {
      const max = 40;
      return Math.min((bmi.value / max) * 100, 100);
    });

    // Taux métabolique de base
    const tmb = computed(() => {
      if (sex === "male") {
        return 10 * weight + 6.25 * height - 5 * age + 5;
      } else {
        return 10 * weight + 6.25 * height - 5 * age - 161;
      }
    });

    // Multiplicateur activité
    const activityMultipliers = {
      sedentary: 1.2,
      slightlyActive: 1.375,
      moderatelyActive: 1.55,
      veryActive: 1.725,
    };

    const dailyNeeds = computed(() => {
      return tmb.value * (activityMultipliers[activityLevel] || 1.2);
    });

    // Calories cibles selon objectif
    const targetCalories = computed(() => {
      if (weightObjective === "loseWeight") {
        return dailyNeeds.value - 500;
      } else if (weightObjective === "gainWeight") {
        return dailyNeeds.value + 300;
      }
      return dailyNeeds.value;
    });

    //Répartition des macros 
    // Besoins protéines (en g/jour)
    const proteinNeeds = computed(() => {
      let gramsPerKg = 1.2;
      if (activityLevel === "moderatelyActive") gramsPerKg = 1.6;
      if (activityLevel === "veryActive" || weightObjective === "gainWeight") gramsPerKg = 2;
      return gramsPerKg * weight;
    });

    // Calories protéines
    const proteinCalories = computed(() => proteinNeeds.value * 4);

    // Lipides : 30% des calories
    const fatCalories = computed(() => targetCalories.value * 0.3);
    const fatNeeds = computed(() => fatCalories.value / 9);

    // Glucides = reste
    const carbCalories = computed(() => targetCalories.value - (proteinCalories.value + fatCalories.value));
    const carbNeeds = computed(() => carbCalories.value / 4);

    return {
      authStore,
      bmi,
      bmiStatus,
      bmiPercent,
      tmb,
      activityLevel,
      weightObjective,
      dailyNeeds,
      targetCalories,
      proteinNeeds,
      fatNeeds,
      carbNeeds,
      proteinCalories,
      fatCalories,
      carbCalories,
    };
  },
};
</script>

