<template>
  <v-container class="py-6">
    <h2 class="text-h5 mb-6">Modifier mon profil</h2>

    <v-form ref="form" v-model="isValid" lazy-validation>
      <v-row>
        <v-col cols="12" v-for="q in questions" :key="q.key">
          <v-card class="mb-4" outlined>
            <v-card-title class="text-subtitle-1">
              {{ $t(q.key) }}
            </v-card-title>
            <v-card-text>
              <!-- Type number -->
              <v-text-field
                v-if="q.type === 'number'"
                v-model="formData[q.key]"
                type="number"
                variant="outlined"
                density="comfortable"
                :label="$t(q.key)"
              />

              <!-- Type radio -->
              <v-radio-group
                v-else-if="q.type === 'radio'"
                v-model="formData[q.key]"
                :label="$t(q.key)"
              >
                <v-radio
                  v-for="opt in q.options"
                  :key="opt.option"
                  :label="$t(opt.option)"
                  :value="opt.option"
                />
              </v-radio-group>

              <!-- Type checkbox -->
              <div v-else-if="q.type === 'checkbox'">
                <v-checkbox
                  v-for="opt in q.options"
                  :key="opt.option"
                  v-model="formData[q.key]"
                  :label="$t(opt.option)"
                  :value="opt.option"
                  hide-details
                  density="comfortable"
                />
              </div>
            </v-card-text>
          </v-card>
        </v-col>
      </v-row>

      <v-btn
        color="primary"
        class="mt-4"
        :disabled="!isValid"
        @click="saveProfile"
      >
        Sauvegarder
      </v-btn>
      <v-btn
        class="mt-4 ml-2"
        variant="outlined"
        @click="resetForm"
      >
        Annuler
      </v-btn>
    </v-form>
  </v-container>
</template>

<script setup>
import { reactive, watch, ref } from "vue"
import { useAuthStore } from "@/store/auth_store"
import questionsData from "@/data/register_questions.json"

const auth = useAuthStore()
const questions = questionsData

// 1) État réactif, pas ref({})
const formData = reactive({})
const isValid = ref(false)

// 2) Surveille user et initialise les champs
watch(
  () => auth.user,
  (u) => {
    if (!u) return
    questions.forEach((q) => {
      if (u[q.key] !== undefined) {
        // copie profonde pour arrays
        formData[q.key] = Array.isArray(u[q.key]) ? [...u[q.key]] : u[q.key]
      } else if (q.type === "checkbox") {
        formData[q.key] = []
      } else {
        formData[q.key] = ""
      }
    })
  },
  { immediate: true }
)

const saveProfile = async () => {
  console.log("Données à sauvegarder :", formData)
  // 👉 appel API pour sauvegarder
  // await api.updateUser(formData)
  auth.user = { ...auth.user, ...formData }
}

const resetForm = () => {
  if (!auth.user) return
  questions.forEach((q) => {
    formData[q.key] = Array.isArray(auth.user[q.key])
      ? [...auth.user[q.key]]
      : auth.user[q.key] ?? (q.type === "checkbox" ? [] : "")
  })
}
</script>
