<template>
  <loading-element v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>
    <TopDeck
      v-if="authStore.userInfos"
      firstElement="Mes"
      secondElement="recettes"
      :coloredSecond="true"
    />

    <v-row class="mt-6" no-gutters>
      <v-col cols="12" md="12" class="pr-2">
        <div class="pa-4 bg-white rounded-lg">
          <div class="d-flex align-center justify-space-between">
            <h3 class="text">Mes recettes</h3>
            <v-btn
              color="accent"
              prepend-icon="mdi-plus"
              elevation="0"
              rounded="lg"
              @click="router.push('/add_recipe')"
            >
              Créer une recette
            </v-btn>
          </div>

          <!-- Recherche -->
          <div class="d-flex align-center my-4" style="gap: 1rem;">
            <v-text-field
              v-model="searchQuery"
              placeholder="Rechercher (titre, catégorie, notes)"
              hide-details
              density="compact"
              variant="tonal"
              prepend-inner-icon="mdi-magnify"
              class="searchField rounded-lg flex-1-1"
              rounded="lg"
            />
          </div>

          <!-- Loader -->
          <div v-if="isLoadingRecipes" class="d-flex justify-center my-10">
            <v-progress-circular indeterminate color="primary" />
          </div>

          <!-- Vide -->
          <v-alert
            v-else-if="!filteredRecipes.length"
            type="info"
            variant="tonal"
            class="mt-4"
          >
            Aucune recette à afficher.
          </v-alert>

          <!-- Grille de recettes -->
          <v-row v-else dense>
            <v-col
              v-for="item in filteredRecipes"
              :key="item.id"
              cols="12" sm="6" md="4"
            >
              <v-card class="recipe-card" outlined>
                <v-card-title class="d-flex justify-space-between align-center">
                  <span class="line-clamp-1">{{ item.title || 'Sans titre' }}</span>
                  <v-btn
                    icon
                    variant="text"
                    :color="item.favorite ? 'warning' : ''"
                    @click="toggleFavoriteOn(item)"
                  >
                    <v-icon>{{ item.favorite ? 'mdi-star' : 'mdi-star-outline' }}</v-icon>
                  </v-btn>
                </v-card-title>

                <v-card-subtitle class="d-flex align-center" v-if="item.category">
                  <v-chip size="small" variant="tonal" color="black">
                    {{ item.category }}
                  </v-chip>
                </v-card-subtitle>

                <v-card-text>
                  <div class="text-caption mb-2" v-if="item.notes">
                    {{ item.notes }}
                  </div>

                  <div class="text-body-2">
                    <strong>Totaux :</strong>
                    {{ (item.totals?.grams ?? 0) }} g —
                    {{ (item.totals?.kcal ?? 0) }} kcal
                    <br>
                    P {{ (item.totals?.protein ?? 0).toFixed ? item.totals.protein.toFixed(1) : item.totals?.protein ?? 0 }} g •
                    G {{ (item.totals?.carbs ?? 0).toFixed ? item.totals.carbs.toFixed(1) : item.totals?.carbs ?? 0 }} g •
                    L {{ (item.totals?.fat ?? 0).toFixed ? item.totals.fat.toFixed(1) : item.totals?.fat ?? 0 }} g
                  </div>

                  <div class="text-caption mt-1" v-if="item.servings && item.servings > 0">
                    <strong>Par portion ({{ item.servings }}) :</strong>
                    {{ Math.round((item.totals?.kcal ?? 0) / item.servings) }} kcal
                  </div>
                </v-card-text>

                <v-card-actions class="justify-end">
                  <v-btn variant="text" @click="router.push({ name: 'recipe_detail', params: { id: item.id } })">
                    Voir
                  </v-btn>
                  <v-btn variant="text" color="error" @click="deleteRecipe(item.id)">
                    Supprimer
                  </v-btn>
                </v-card-actions>
              </v-card>
            </v-col>
          </v-row>
        </div>
      </v-col>
    </v-row>

    <v-snackbar v-if="errorMessage" color="error" timeout="3000" top right>
      {{ errorMessage }}
    </v-snackbar>
  </div>
</template>

<script>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import LoadingElement from "@/components/Animations/LoadingElement.vue";
import TopDeck from "@/components/Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import {
  getUserRecipes,
  deleteRecipeFromUserCollection,
  setRecipeAsFavorite,
} from "@/service/recipe_service";

export default {
  name: "MyRecipes",
  components: { LoadingElement, TopDeck },
  setup() {
    const authStore = useAuthStore();
    const errorMessage = ref("");
    const router = useRouter();

    const recipes = ref([]);            // [{ id, title, category, notes, totals, servings, favorite }]
    const isLoadingRecipes = ref(false);
    const selectedRecipe = ref(null);
    const searchQuery = ref("");

    const filteredRecipes = computed(() => {
      const q = searchQuery.value.trim().toLowerCase();
      if (!q) return recipes.value;
      return recipes.value.filter((item) => {
        const title = (item.title || "").toLowerCase();
        const category = (item.category || "").toLowerCase();
        const notes = (item.notes || "").toLowerCase();
        return title.includes(q) || category.includes(q) || notes.includes(q);
      });
    });

    function select(item) {
      selectedRecipe.value = item;
      // Tu peux ouvrir un drawer ou une page détail si besoin
    }

    async function deleteRecipe(id) {
      if (!id || !authStore.userInfos?.userid) return;
      try {
        await deleteRecipeFromUserCollection(authStore.userInfos.userid, id);
        recipes.value = recipes.value.filter((r) => r.id !== id);
      } catch (err) {
        console.error("❌ Erreur suppression :", err);
        errorMessage.value = "Erreur lors de la suppression de la recette.";
      }
    }

    async function toggleFavoriteOn(item) {
      if (!item?.id || !authStore.userInfos?.userid) return;
      try {
        const newValue = !item.favorite;
        await setRecipeAsFavorite(authStore.userInfos.userid, item.id, newValue);
        item.favorite = newValue; // MAJ locale
        if (selectedRecipe.value?.id === item.id) {
          selectedRecipe.value.favorite = newValue;
        }
      } catch (err) {
        console.error("❌ Erreur favoris :", err);
        errorMessage.value = "Erreur lors de la mise à jour du favori.";
      }
    }

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async (newUserInfos) => {
          if (!newUserInfos?.userid) return;
          try {
            isLoadingRecipes.value = true;
            const data = await getUserRecipes(newUserInfos.userid);
            // data = { recipeId: {title, ...}, ... }
            recipes.value = Object.entries(data).map(([id, value]) => ({
              id,
              ...value,
            }));
          } catch (error) {
            console.error("Erreur récupération recettes:", error);
            errorMessage.value = "Erreur lors du chargement des recettes.";
          } finally {
            isLoadingRecipes.value = false;
          }
        },
        { immediate: true }
      );
    });

    return {
      authStore,
      errorMessage,
      router,
      recipes,
      selectedRecipe,
      select,
      searchQuery,
      filteredRecipes,
      isLoadingRecipes,
      deleteRecipe,
      toggleFavoriteOn,
    };
  },
};
</script>

<style scoped>
  .searchField {
    background-color: rgb(244, 244, 244);
  }
  .recipe-card {
    border-radius: 12px;
  }
  .line-clamp-1 {
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
</style>
