<!-- src/views/CreateRecipe.vue -->
<template>
  <v-container class="py-6">
    <h2 class="text-h5 mb-6">{{ pageTitle }}</h2>

    <v-form ref="form" v-model="isValid" lazy-validation>
      <!-- Métadonnées recette -->
      <v-card outlined class="mb-6">
        <v-card-title class="text-h6">Informations recette</v-card-title>
        <v-card-text>
          <v-row>
            <v-col cols="12" md="6">
              <v-text-field v-model="recipe.title" label="Nom de la recette" variant="outlined" required />
            </v-col>
            <v-col cols="6" md="3">
              <v-text-field v-model.number="recipe.servings" type="number" min="1" label="Portions" variant="outlined" />
            </v-col>
            <v-col cols="6" md="3">
              <v-combobox
                v-model="recipe.category"
                :items="recipeCategories"
                label="Catégorie"
                clearable
                variant="outlined"
              />
            </v-col>
            <v-col cols="12">
              <v-textarea v-model="recipe.notes" label="Notes (optionnel)" variant="outlined" rows="2" />
            </v-col>
          </v-row>
        </v-card-text>
      </v-card>

      <v-row>
        <!-- 1) Sélection d’ingrédients -->
        <v-col cols="12" md="7">
          <v-card outlined>
            <v-card-title class="justify-space-between">
              <span class="text-h6">Ajouter des ingrédients</span>
            </v-card-title>

            <v-card-text>
              <v-text-field
                v-model="searchQuery"
                placeholder="Rechercher par nom, marque ou catégorie…"
                prepend-inner-icon="mdi-magnify"
                variant="outlined"
                density="comfortable"
                clearable
              />

              <v-skeleton-loader v-if="isLoadingIngredients" type="list-item-two-line@6" class="mt-2" />
              <div v-else>
                <v-alert v-if="!ingredients.length" type="info" variant="tonal" class="mb-2">
                  Aucun ingrédient dans votre collection pour l’instant.
                </v-alert>

                <v-alert v-else-if="!filteredIngredients.length" type="warning" variant="tonal" class="mb-2">
                  Aucun résultat pour « {{ searchQuery }} ».
                </v-alert>

                <v-virtual-scroll :items="filteredIngredients" height="360">
                  <template #default="{ item }">
                    <v-list-item
                      :title="item.productName"
                      :subtitle="subtitleFor(item)"
                      class="px-2"
                    >
                      <template #append>
                        <v-btn size="small" variant="tonal" class="mr-2" @click="openAddDialog(item)">
                          Ajouter
                        </v-btn>
                      </template>
                    </v-list-item>
                    <v-divider />
                  </template>
                </v-virtual-scroll>
              </div>
            </v-card-text>
          </v-card>
        </v-col>

        <!-- 2) Ingrédients de la recette -->
        <v-col cols="12" md="5">
          <v-card outlined>
            <v-card-title class="text-h6">Ingrédients sélectionnés</v-card-title>
            <v-card-text>
              <v-alert v-if="!recipeIngredients.length" type="info" variant="tonal" class="mb-4">
                Aucun ingrédient ajouté pour l’instant.
              </v-alert>

              <div v-else class="mb-4">
                <v-row
                  v-for="(line, idx) in recipeIngredients"
                  :key="line.id"
                  align="center"
                  class="py-1"
                >
                  <v-col cols="7">
                    <div class="font-medium">{{ line.productName }}</div>
                    <div class="text-caption text-medium-emphasis">{{ line.productBrand || '—' }}</div>
                  </v-col>
                  <v-col cols="5" class="d-flex align-center justify-end">
                    <v-text-field
                      v-model.number="line.grams"
                      type="number"
                      min="0"
                      step="1"
                      suffix="g"
                      hide-details
                      density="compact"
                      style="max-width: 120px"
                      @change="clampGrams(line)"
                    />
                    <v-btn icon variant="text" color="error" @click="removeLine(idx)" class="ml-2">
                      <v-icon>mdi-close</v-icon>
                    </v-btn>
                  </v-col>

                  <v-col cols="12" class="py-0">
                    <div class="text-caption">
                      ≈ {{ kcalFor(line).toFixed(0) }} kcal — Prot {{ protFor(line).toFixed(1) }} g • Gras {{ carbsFor(line).toFixed(1) }} g • Lip {{ fatFor(line).toFixed(1) }} g
                    </div>
                  </v-col>

                  <v-divider class="my-2" />
                </v-row>
              </div>

              <!-- Totaux -->
              <v-sheet class="pa-3 rounded-lg bg-grey-lighten-4">
                <div class="text-subtitle-2 mb-1">Totaux recette</div>
                <div class="text-body-2">
                  {{ totalGrams }} g — {{ totals.kcal.toFixed(0) }} kcal
                  <br>
                  P {{ totals.protein.toFixed(1) }} g • G {{ totals.carbs.toFixed(1) }} g • L {{ totals.fat.toFixed(1) }} g
                </div>
                <div v-if="recipe.servings > 0" class="text-caption mt-2">
                  <strong>Par portion ({{ recipe.servings }}):</strong>
                  {{ (totals.kcal / recipe.servings).toFixed(0) }} kcal —
                  Prot {{ (totals.protein / recipe.servings).toFixed(1) }} g •
                  Gras {{ (totals.carbs / recipe.servings).toFixed(1) }} g •
                  Lip {{ (totals.fat / recipe.servings).toFixed(1) }} g
                </div>
              </v-sheet>
            </v-card-text>
          </v-card>
        </v-col>
      </v-row>

      <!-- Actions -->
      <div class="mt-6">
        <v-btn color="primary" :disabled="!canSave" @click="saveRecipe">
          Enregistrer la recette
        </v-btn>
        <v-btn class="ml-2" variant="outlined" @click="resetRecipe">Réinitialiser</v-btn>
      </div>

      <!-- Dialog ajout avec grammes -->
      <v-dialog v-model="addDialog.open" max-width="480">
        <v-card>
          <v-card-title>Ajouter « {{ addDialog.item?.productName }} »</v-card-title>
          <v-card-text>
            <v-text-field
              v-model.number="addDialog.grams"
              type="number"
              min="0"
              label="Quantité (g)"
              variant="outlined"
            />
            <div class="text-caption mt-1">
              Réf. 100 g : {{ nutritionLine(addDialog.item) }}
            </div>
          </v-card-text>
          <v-card-actions>
            <v-spacer/>
            <v-btn variant="text" @click="addDialog.open=false">Annuler</v-btn>
            <v-btn color="primary" @click="confirmAdd">Ajouter</v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>

      <!-- Messages -->
      <v-snackbar v-model="snack.show" :timeout="2500">
        {{ snack.text }}
      </v-snackbar>
      <v-alert v-if="errorMessage" type="error" variant="tonal" class="mt-4">
        {{ errorMessage }}
      </v-alert>
    </v-form>
  </v-container>
</template>

<script setup>
  import { ref, computed, onMounted, watch } from 'vue'
  import { useRoute } from 'vue-router'
  import { useAuthStore } from '@/store/auth_store'
  import { getUserIngredients } from "@/service/food_service"
  import { addRecipeForUser, updateRecipeForUser, getUserRecipeById } from '@/service/recipe_service'

  const authStore = useAuthStore()

  /** ------- Données UI ------- **/
  const recipeCategories = ['Entrée', 'Plat', 'Dessert', 'Boisson']

  const editId = ref(null) // id de recette si mode édition
  const isEdit = computed(() => !!editId.value)
  const route = useRoute()
  const pageTitle = computed(() => isEdit.value ? 'Modifier la recette' : 'Créer une recette')

  const recipe = ref({
    title: '',
    servings: 1,
    category: null,
    notes: ''
  })

  const ingredients = ref([])                 // normalisés en tableau [{id, ...}]
  const isLoadingIngredients = ref(false)
  const errorMessage = ref('')

  const searchQuery = ref('')
  const recipeIngredients = ref([])

  const snack = ref({ show: false, text: '' })
  const isValid = ref(true)

  /** ---------- Helpers Firestore → JS ---------- **/
  function unwrapFirestoreValue(v) {
    if (v == null) return null
    if (v.stringValue !== undefined) return v.stringValue
    if (v.doubleValue !== undefined) return v.doubleValue
    if (v.integerValue !== undefined) return Number(v.integerValue)
    if (v.booleanValue !== undefined) return v.booleanValue
    if (v.arrayValue !== undefined) {
      const arr = v.arrayValue.values || []
      return arr.map(unwrapFirestoreValue)
    }
    if (v.mapValue !== undefined) {
      const out = {}
      const f = v.mapValue.fields || {}
      for (const k of Object.keys(f)) out[k] = unwrapFirestoreValue(f[k])
      return out
    }
    return v
  }

  function parseNumberFromString(s) {
    const m = String(s ?? '').match(/-?\d+(\.\d+)?/)
    return m ? Number(m[0]) : 0
  }

  function parseNutrimentsMap(nutrimentsMap) {
    // nutrimentsMap attendu: [{ key:'energy-kcal', value:'264 kcal' }, ...]
    const out = { kcal:0, protein:0, carbs:0, fat:0, sugars:0, salt:0, fiber:0, satFat:0 }
    if (!Array.isArray(nutrimentsMap)) return out
    for (const it of nutrimentsMap) {
      const key = it?.key
      const val = parseNumberFromString(it?.value)
      switch (key) {
        case 'energy-kcal': out.kcal = val; break
        case 'proteins': out.protein = val; break
        case 'carbohydrates': out.carbs = val; break
        case 'fat': out.fat = val; break
        case 'sugars': out.sugars = val; break
        case 'salt': out.salt = val; break
        case 'fiber': out.fiber = val; break
        case 'saturated-fat': out.satFat = val; break
      }
    }
    return out
  }

  function normalizeFirestoreIngredients(raw) {
    // Cas 1: le service renvoie déjà un objet simple { barcode: { ... } }
    if (raw && !raw.fields) {
      return Object.entries(raw).map(([id, val]) => {
        const nutritionPer100g =
          val.nutritionPer100g ||
          parseNutrimentsMap(val.nutriments_map) ||
          {}
        return {
          id,
          productName: val.productName || '',
          productBrand: val.productBrand || '',
          category: val.category || '',
          favorite: !!val.favorite,
          productImage: val.productImage || '',
          servingSize: val.servingSize || '',
          servingQuantity: val.servingQuantity ?? '',
          allergens: Array.isArray(val.allergens) ? val.allergens : [],
          labels: Array.isArray(val.labels) ? val.labels : [],
          novaGroup: val.novaGroup || null,
          nutriments_map: val.nutriments_map || [],
          nutritionPer100g,
        }
      })
    }

    // Cas 2: payload Firestore proto (document.fields.*)
    const fields = raw?.fields
    if (!fields) return []
    const asObject = unwrapFirestoreValue({ mapValue: { fields } }) // => { barcode: { ...js } }
    return Object.entries(asObject).map(([id, val]) => {
      const nutritionPer100g =
        parseNutrimentsMap(val.nutriments_map) || {}
      return {
        id,
        productName: val.productName || '',
        productBrand: val.productBrand || '',
        category: val.category || '',
        favorite: !!val.favorite,
        productImage: val.productImage || '',
        servingSize: val.servingSize || '',
        servingQuantity: val.servingQuantity ?? '',
        allergens: Array.isArray(val.allergens) ? val.allergens : [],
        labels: Array.isArray(val.labels) ? val.labels : [],
        novaGroup: val.novaGroup || null,
        nutriments_map: val.nutriments_map || [],
        nutritionPer100g,
      }
    })
  }

  // ------- Chargement ingrédients user + édition -------
  onMounted(() => {
    // récupère l'id si présent en query: /add_recipe?id=xxx
    editId.value = typeof route.query.id === 'string' ? route.query.id : null

    watch(
      () => authStore.userInfos,
      async (newUser) => {
        if (!newUser?.userid) return
        try {
          isLoadingIngredients.value = true
          const data = await getUserIngredients(newUser.userid)
          ingredients.value = normalizeFirestoreIngredients(data)
          // après avoir les ingrédients, si on est en mode édition -> hydrate
          await tryHydrateEdit()
        } catch (e) {
          console.error('Erreur récupération ingrédients:', e)
          errorMessage.value = "Erreur lors du chargement des ingrédients."
        } finally {
          isLoadingIngredients.value = false
        }
      },
      { immediate: true }
    )

    // si l’id dans l’URL change en live (rare), on tente l’hydratation
    watch(() => route.query.id, (val) => {
      editId.value = typeof val === 'string' ? val : null
      hydratedOnce = false
      tryHydrateEdit()
    })
  })

  /** ------- Recherche ------- **/
  const filteredIngredients = computed(() => {
    const q = searchQuery.value.trim().toLowerCase()
    if (!q) return ingredients.value
    return ingredients.value.filter((item) => {
      return ['productName', 'productBrand', 'category'].some((key) => {
        return (item[key] ?? '').toLowerCase().includes(q)
      })
    })
  })

  /** ------- Sélection / favoris / suppression ------- **/
  //function select(item) { selectedIngredient.value = item }

  /** ------- Ajout à la recette ------- **/
  const addDialog = ref({ open: false, item: null, grams: 100 })

  function openAddDialog(item) {
    addDialog.value = { open: true, item, grams: 100 }
  }

  function extractPer100g(item) {
    // priorité : nutritionPer100g normalisé, sinon parse nutriments_map
    if (item?.nutritionPer100g) return item.nutritionPer100g
    return parseNutrimentsMap(item?.nutriments_map || [])
  }

  // --------- Pré-remplissage en mode édition ----------
  let hydratedOnce = false

  async function tryHydrateEdit() {
    if (!isEdit.value || hydratedOnce) return
    if (!authStore.userInfos?.userid) return
    // on a besoin que la collection d’ingrédients soit dispo pour hydrater joliment
    if (!ingredients.value.length) return

    try {
      // 🔹 Récupère UNIQUEMENT cette recette
      const r = await getUserRecipeById(authStore.userInfos.userid, editId.value)
      if (!r) {
        errorMessage.value = 'Recette introuvable.'
        return
      }

      // Pré-remplir meta
      recipe.value = {
        title: r.title || '',
        servings: Number(r.servings || 1),
        category: r.category ?? null,
        notes: r.notes || ''
      }

      // Hydrater lignes ingréds [{id, grams}] -> [{id, grams, productName, brand, nutritionPer100g}]
      const lines = Array.isArray(r.ingredients) ? r.ingredients : []
      recipeIngredients.value = lines.map((l) => {
        const found = ingredients.value.find(it => it.id === l.id)
        return {
          id: l.id,
          grams: Number(l.grams || 0),
          productName: found?.productName || l.id,
          productBrand: found?.productBrand || '',
          nutritionPer100g: extractPer100g(found) // {} si pas trouvé
        }
      })

      hydratedOnce = true
    } catch (e) {
      console.error('❌ Hydratation édition échouée:', e)
      errorMessage.value = "Impossible de pré-remplir la recette."
    }
  }

  function confirmAdd() {
    const { item, grams } = addDialog.value
    if (!item || grams <= 0) return
    const existing = recipeIngredients.value.find(l => l.id === item.id)
    if (existing) {
      existing.grams += Number(grams)
    } else {
      recipeIngredients.value.push({
        id: item.id,
        productName: item.productName,
        productBrand: item.productBrand,
        grams: Number(grams),
        nutritionPer100g: extractPer100g(item)
      })
    }
    addDialog.value.open = false
  }

  function removeLine(index) { recipeIngredients.value.splice(index, 1) }
  function clampGrams(line) {
    if (line.grams == null || isNaN(line.grams) || line.grams < 0) line.grams = 0
  }

  /** ------- Nutrition & totaux ------- **/
  function factor(line) { return (line.grams || 0) / 100 }
  function kcalFor(line)  { return (line.nutritionPer100g.kcal   || 0) * factor(line) }
  function protFor(line)  { return (line.nutritionPer100g.protein|| 0) * factor(line) }
  function carbsFor(line) { return (line.nutritionPer100g.carbs  || 0) * factor(line) }
  function fatFor(line)   { return (line.nutritionPer100g.fat    || 0) * factor(line) }

  const totals = computed(() => {
    return recipeIngredients.value.reduce((acc, l) => {
      const f = factor(l)
      acc.kcal   += (l.nutritionPer100g.kcal    || 0) * f
      acc.protein+= (l.nutritionPer100g.protein || 0) * f
      acc.carbs  += (l.nutritionPer100g.carbs   || 0) * f
      acc.fat    += (l.nutritionPer100g.fat     || 0) * f
      acc.sugars += (l.nutritionPer100g.sugars  || 0) * f
      acc.salt   += (l.nutritionPer100g.salt    || 0) * f
      return acc
    }, { kcal:0, protein:0, carbs:0, fat:0, sugars:0, salt:0 })
  })

  const totalGrams = computed(() =>
    recipeIngredients.value.reduce((s, l) => s + (l.grams || 0), 0)
  )

  /** ------- Helpers UI ------- **/
  function subtitleFor(item) {
    const left = [item.productBrand, item.category].filter(Boolean).join(' • ')
    const n = extractPer100g(item)
    const right = `${n.kcal || 0} kcal / 100 g`
    return left ? `${left}  —  ${right}` : right
  }
  function nutritionLine(item) {
    const n = extractPer100g(item)
    return `${n.kcal || 0} kcal • P ${n.protein || 0} g • G ${n.carbs || 0} g • L ${n.fat || 0} g / 100 g`
  }

  /** ------- Validation & Enregistrement ------- **/
  const canSave = computed(() => {
    return !!recipe.value.title && recipeIngredients.value.length > 0 && isValid.value
  })

  async function saveRecipe() {
    if (!authStore.userInfos?.userid) {
      errorMessage.value = "Utilisateur non connecté."
      return
    }
    const payload = {
      date: Date.now(),
      title: recipe.value.title,
      category: recipe.value.category || null,
      servings: Number(recipe.value.servings || 1),
      notes: recipe.value.notes || '',
      ingredients: recipeIngredients.value.map(l => ({ id: l.id, grams: l.grams })),
      totals: {
        grams: totalGrams.value,
        kcal: Number(totals.value.kcal.toFixed(0)),
        protein: Number(totals.value.protein.toFixed(1)),
        carbs: Number(totals.value.carbs.toFixed(1)),
        fat: Number(totals.value.fat.toFixed(1)),
        sugars: Number(totals.value.sugars.toFixed(1)),
        salt: Number(totals.value.salt.toFixed(2))
      }
    }

    try {
      if (isEdit.value) {
        // UPDATE
        await updateRecipeForUser(authStore.userInfos.userid, editId.value, {
          ...payload,
          // si tu veux conserver une date de création existante, ne remets pas createdAt
          updatedAt: Date.now(),
        })
        snack.value = { show: true, text: 'Recette mise à jour ✅' }
      } else {
        // CREATE
        await addRecipeForUser(authStore.userInfos.userid, {
          ...payload,
          createdAt: Date.now(),
        })
        snack.value = { show: true, text: 'Recette enregistrée ✅' }
        resetRecipe()
      }
    } catch (e) {
      console.error('Erreur enregistrement recette:', e)
      errorMessage.value = isEdit.value
        ? "Erreur lors de la mise à jour de la recette."
        : "Erreur lors de l’enregistrement de la recette."
    }
  }

  function resetRecipe() {
    recipe.value = { title: '', servings: 1, category: null, notes: '' }
    searchQuery.value = ''
    recipeIngredients.value = []
  }
</script>